CREATE OR REPLACE FUNCTION platform_private.notification_source_client(st text,sid uuid) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE cid uuid; BEGIN CASE st WHEN 'registros_consultor','registro_consultor','monitoramento_vencido' THEN SELECT cliente_id INTO cid FROM public.registros_consultor WHERE id=sid; WHEN 'portal_solicitacoes' THEN SELECT cliente_id INTO cid FROM public.portal_solicitacoes WHERE id=sid; WHEN 'ordem_servico','ordens_servico' THEN SELECT cliente_id INTO cid FROM public.ordens_servico WHERE id=sid; WHEN 'aplicacao','aplicacoes' THEN SELECT o.cliente_id INTO cid FROM public.aplicacoes a JOIN public.ordens_servico o ON o.id=a.ordem_servico_id WHERE a.id=sid AND a.ordem_servico_onfarm_id IS NULL; ELSE RETURN NULL; END CASE; RETURN cid; END $$;
REVOKE ALL ON FUNCTION platform_private.notification_source_client(text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION platform_private.notification_source_client(text,uuid) TO service_role;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('platform_private.notification_source_org(text,uuid)'::regprocedure) INTO d; d:=replace(d,'WHEN ''estoque_produto'' THEN SELECT l.organization_id INTO v FROM public.estoque_produto e JOIN public.lotes l ON l.id=e.lote_id WHERE e.id=sid;','WHEN ''estoque_produto'' THEN RETURN NULL;'); IF d LIKE '%JOIN public.lotes l ON l.id=e.lote_id%' THEN RAISE EXCEPTION 'BASELINE_MISMATCH'; END IF; EXECUTE d;
SELECT pg_get_functiondef('platform_private.notification_p1_visible(uuid,text,uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'IF cid IS NOT NULL THEN','IF cid IS NOT NULL THEN'||chr(10)||'IF platform_private.notification_source_client(st,sid) IS DISTINCT FROM cid THEN RETURN false; END IF;'); IF position('notification_source_client' in d)=0 THEN RAISE EXCEPTION 'BASELINE_MISMATCH'; END IF; EXECUTE d;
SELECT pg_get_functiondef('platform_private.notification_p1_guard()'::regprocedure) INTO d; d:=replace(d,'IF cid IS NOT NULL AND (','IF cid IS NOT NULL AND (platform_private.notification_source_client(NEW.source_type,NEW.source_id) IS DISTINCT FROM cid OR '); IF position('notification_source_client' in d)=0 THEN RAISE EXCEPTION 'BASELINE_MISMATCH'; END IF; EXECUTE d; END $$;